arguments.file_text:
@page "/recipes"
@page "/recipes/{Category}"

@inject RecipeShare.Services.RecipeService RecipeService

<PageTitle>Recipes - @(Category ?? "All Categories")</PageTitle>

@if (string.IsNullOrEmpty(Category))
{
    <h1>All Categories</h1>
    <ul>
        @foreach (var cat in RecipeService.GetCategories())
        {
            <li><a href="recipes/@cat">@cat</a></li>
        }
    </ul>
}
else
{
    <h1>@Category Recipes</h1>
    <nav aria-label="breadcrumb">
        <ol class="breadcrumb">
            <li class="breadcrumb-item"><a href="/">Home</a></li>
            <li class="breadcrumb-item"><a href="/recipes">Recipes</a></li>
            <li class="breadcrumb-item active">@Category</li>
        </ol>
    </nav>

    var recipes = RecipeService.GetRecipesByCategory(Category);
    @if (recipes.Count == 0)
    {
        <p>No recipes found in this category.</p>
    }
    else
    {
        <div class="row">
            @foreach (var recipe in recipes)
            {
                <div class="col-md-6 mb-3">
                    <div class="card h-100">
                        <div class="card-body">
                            <h5 class="card-title">@recipe.Title</h5>
                            <p class="card-text">
                                @if (recipe.RatingCount > 0)
                                {
                                    <span>⭐ @recipe.AverageRating / 5 (@recipe.RatingCount ratings)</span>
                                }
                                else
                                {
                                    <span class="text-muted">No ratings yet</span>
                                }
                            </p>
                            <a href="recipe/@recipe.Id" class="btn btn-outline-primary">View Recipe</a>
                        </div>
                    </div>
                </div>
            }
        </div>
    }
}

@code {
    [Parameter]
    public string? Category { get; set; }
}

@page "/recipe/{Id:int}"

@inject RecipeShare.Services.RecipeService RecipeService

<PageTitle>@(recipe?.Title ?? "Recipe Not Found")</PageTitle>

@if (recipe is null)
{
    <h1>Recipe Not Found</h1>
    <p>The recipe you're looking for doesn't exist.</p>
    <a href="/recipes" class="btn btn-primary">Browse Recipes</a>
}
else
{
    <nav aria-label="breadcrumb">
        <ol class="breadcrumb">
            <li class="breadcrumb-item"><a href="/">Home</a></li>
            <li class="breadcrumb-item"><a href="/recipes/@recipe.Category">@recipe.Category</a></li>
            <li class="breadcrumb-item active">@recipe.Title</li>
        </ol>
    </nav>

    <h1>@recipe.Title</h1>
    <span class="badge bg-secondary mb-3">@recipe.Category</span>

    <h3>Ingredients</h3>
    <ul>
        @foreach (var ingredient in recipe.Ingredients.Split(',', StringSplitOptions.TrimEntries))
        {
            <li>@ingredient</li>
        }
    </ul>

    <h3>Steps</h3>
    <div class="mb-4">
        @foreach (var step in recipe.Steps.Split('\n', StringSplitOptions.RemoveEmptyEntries))
        {
            <p>@step</p>
        }
    </div>

    <h3>Rating</h3>
    @if (recipe.RatingCount > 0)
    {
        <p>⭐ @recipe.AverageRating / 5 (@recipe.RatingCount ratings)</p>
    }
    else
    {
        <p class="text-muted">No ratings yet. Be the first to rate!</p>
    }

    <StarRating RecipeId="@recipe.Id" @rendermode="InteractiveServer" />
}

@code {
    [Parameter]
    public int Id { get; set; }

    private RecipeShare.Models.Recipe? recipe;

    protected override void OnInitialized()
    {
        recipe = RecipeService.GetRecipeById(Id);
    }
}

@rendermode InteractiveServer

@inject RecipeShare.Services.RecipeService RecipeService

<div class="star-rating my-3">
    <p><strong>Rate this recipe:</strong></p>
    <div style="font-size: 1.5rem; cursor: pointer;">
        @for (int i = 1; i <= 5; i++)
        {
            var star = i;
            <span @onclick="() => SubmitRating(star)"
                  @onmouseover="() => hoverStar = star"
                  @onmouseout="() => hoverStar = 0"
                  style="color: @(GetStarColor(star))">
                @(star <= GetDisplayStar() ? "★" : "☆")
            </span>
        }
    </div>
    @if (submitted)
    {
        <div class="alert alert-success mt-2" role="alert">
            Thank you! You rated this recipe @selectedStar out of 5 stars.
        </div>
    }
</div>

@code {
    [Parameter]
    public int RecipeId { get; set; }

    private int hoverStar;
    private int selectedStar;
    private bool submitted;

    private int GetDisplayStar() => hoverStar > 0 ? hoverStar : selectedStar;

    private string GetStarColor(int star)
    {
        if (star <= GetDisplayStar())
            return "#ffc107";
        return "#dee2e6";
    }

    private void SubmitRating(int stars)
    {
        selectedStar = stars;
        RecipeService.AddRating(RecipeId, stars);
        submitted = true;
    }
}

@page "/submit"
@rendermode InteractiveServer

@inject RecipeShare.Services.RecipeService RecipeService

<PageTitle>Submit a Recipe</PageTitle>

<h1>Submit a Recipe</h1>
<p>Share your favorite recipe with the community!</p>

@if (submitted)
{
    <div class="alert alert-success" role="alert">
        <h4>Recipe Submitted!</h4>
        <p>Your recipe "<strong>@title</strong>" has been added. <a href="/recipes/@category">View it now</a>.</p>
    </div>
    <button class="btn btn-primary" @onclick="Reset">Submit Another</button>
}
else
{
    <EditForm Model="@this" OnValidSubmit="HandleSubmit" FormName="submitRecipe">
        <DataAnnotationsValidator />

        <div class="mb-3">
